function validate([rows, cols, rStart, cStart]) {
  if (![rows, cols, rStart, cStart].every(Number.isInteger)) return 'All four arguments are integers.';
  if (rows < 1 || rows > 100 || cols < 1 || cols > 100) return 'rows and cols are between 1 and 100.';
  if (rStart < 0 || rStart >= rows || cStart < 0 || cStart >= cols) return 'The start cell must lie inside the grid.';
  return null;
}

