function spiralMatrixIII(rows, cols, rStart, cStart) {
  // Walk the unbounded plane, turning right whenever the cell on the right has not been visited yet.
  const seen = new Set([`${rStart},${cStart}`]);
  const out = [[rStart, cStart]];
  const moves = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let r = rStart, c = cStart, d = 0;
  while (out.length < rows * cols) {
    r += moves[d][0];
    c += moves[d][1];
    seen.add(`${r},${c}`);
    if (r >= 0 && r < rows && c >= 0 && c < cols) out.push([r, c]);
    const right = (d + 1) % 4;
    if (!seen.has(`${r + moves[right][0]},${c + moves[right][1]}`)) d = right;
  }
  return out;
}

