function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? int(80, 100) : int(1, 6);
  const cols = size === 'large' ? int(80, 100) : int(1, 6);
  return [rows, cols, int(0, rows - 1), int(0, cols - 1)];
}
